import { extend } from '../vue'
import { PROP_TYPE_BOOLEAN } from '../constants/props'

// --- Props ---

export const props = {
  plain: {
    type: PROP_TYPE_BOOLEAN,
    required: false,
    default: false
  }
}

// --- Mixin ---

// @vue/component
export const formCustomMixin = extend({
  props,
  computed: {
    custom() {
      return !this.plain
    }
  }
})
